//#region lib/types/templates.js
/** Curated source-backed presentation templates. */
function kimiTemplate(definition) {
	const shared = {
		id: OfficeTemplateId(definition.id),
		name: definition.name,
		description: definition.description,
		origin: "built-in",
		supportedModes: ["ppt"],
		category: definition.category,
		sourceCollection: definition.sourceCollection,
		variantLabel: definition.variantLabel,
		aspectRatio: "wide",
		titleFontFace: definition.titleFontFace,
		bodyFontFace: definition.bodyFontFace,
		palette: definition.palette,
		previewTitle: definition.previewTitle,
		previewSubtitle: definition.previewSubtitle
	};
	if (definition.id !== "moss-green-transformation") return shared;
	return enrichTemplateVisualSemantics({
		...MOSS_GREEN_TRANSFORMATION_TEMPLATE_DATA,
		...shared,
		palette: MOSS_GREEN_TRANSFORMATION_TEMPLATE_DATA.palette
	});
}
/** Complete source-indexed template for the Slides and Tencent/SlideP workflow. */
const DATA_ANALYSIS_TEMPLATE = enrichTemplateVisualSemantics({
	id: OfficeTemplateId("data-analysis"),
	origin: "built-in",
	...DATA_ANALYSIS_TEMPLATE_DATA,
	supportedModes: ["slides"]
});
/** Second complete source-indexed template for the Slides and Tencent/SlideP workflow. */
const VITALITY_BLUE_TEMPLATE = enrichTemplateVisualSemantics({
	id: OfficeTemplateId("vitality-blue"),
	origin: "built-in",
	...VITALITY_BLUE_TEMPLATE_DATA,
	supportedModes: ["slides"]
});
/** Both presentation workflows share one catalog while retaining explicit mode ownership. */
const BUILT_IN_TEMPLATES = [
	...[kimiTemplate(KIMI_PPT_TEMPLATE_DEFINITIONS[0]), ...KIMI_PPT_TEMPLATE_DEFINITIONS.slice(1).map(kimiTemplate)],
	DATA_ANALYSIS_TEMPLATE,
	VITALITY_BLUE_TEMPLATE
];
